#!/usr/bin/env node

import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";

import { stableBindingId } from "./lib/binding-identity.mjs";

const root = new URL("../", import.meta.url);
const urls = {
  ir: new URL("bindings/generated/defold-script-api-ir.json", root),
  patterns: new URL("bindings/generated/defold-script-binding-patterns.json", root),
  override: new URL("bindings/overrides/script-url-address-classification.json", root),
  output: new URL("bindings/generated/defold-script-url-address-classification.json", root),
  header: new URL("defold/defold_hermes/include/defold_hermes/generated_script_url_bindings.hpp", root),
  source: new URL("defold/defold_hermes/src/generated_script_url_bindings.cpp", root),
  target: new URL("packages/sdk/src/generated/script/url-target-support.ts", root)
};

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function parse(text, label) {
  try { return JSON.parse(text); }
  catch (error) { throw new Error(`${label} is not valid JSON: ${error.message}`); }
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

function compare(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function uniqueMap(rows, label) {
  const result = new Map();
  for (const row of rows) {
    assert(typeof row.id === "string" && row.id.length > 0, `${label} contains a row without an id`);
    assert(!result.has(row.id), `${label} contains duplicate id '${row.id}'`);
    result.set(row.id, row);
  }
  return result;
}

function countBy(values, select) {
  const counts = {};
  for (const value of values) {
    const key = select(value);
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return Object.fromEntries(Object.entries(counts).sort(([a], [b]) => compare(a, b)));
}

function allTypes(fn) {
  return [...fn.parameters.map(({ rawType }) => rawType), ...fn.returns];
}

function formsFor(rawType) {
  if (rawType === "string|hash|url") return ["string-shorthand", "hash-shorthand", "full-url"];
  if (rawType === "url|number|nil") return ["full-url", "numeric-camera-id", "nil-default"];
  throw new Error(`unreviewed URL parameter type '${rawType}'`);
}

function split(rawType) {
  return rawType.split("|").map((part) => part.trim()).filter(Boolean);
}

const TYPE_CODECS = new Map([
  ["nil", "Nil"], ["boolean", "Boolean"], ["integer", "Integer"],
  ["number", "Number"], ["string", "String"], ["hash", "Hash"],
  ["url", "Url"], ["vector3", "Vector3"], ["vector4", "Vector4"],
  ["quaternion", "Quaternion"]
]);

function codecsFor(rawType, optional, id) {
  const codecs = split(rawType).map((type) => TYPE_CODECS.get(type) ??
    (/^[A-Za-z_][A-Za-z0-9_.]*$/.test(type) ? "Integer" : null));
  assert(codecs.every(Boolean), `${id}: unsupported generated URL argument type '${rawType}'`);
  if (optional && !codecs.includes("Nil")) codecs.push("Nil");
  return [...new Set(codecs)];
}

function resultCodecFor(returns, id) {
  assert(returns.length <= 1, `${id}: URL dispatcher requires a scalar or void result`);
  if (returns.length === 0) return "None";
  const rawType = returns[0];
  if (rawType === "hash|nil") return "HashOrNil";
  const codecs = codecsFor(rawType, false, id);
  assert(codecs.length === 1, `${id}: unsupported generated URL result union '${rawType}'`);
  const codec = codecs[0];
  if (codec === "Nil" || codec === "Url") return codec;
  return codec === "Integer" ? "Integer" : codec;
}

function cpp(value) {
  return JSON.stringify(value).replaceAll("\u2028", "\\u2028").replaceAll("\u2029", "\\u2029");
}

function renderRuntime(report) {
  const rows = [...report.rows].sort((a, b) => a.stableId - b.stableId);
  let argumentOffset = 0;
  const descriptors = rows.map((row, index) => {
    const descriptor = { ...row, index, argumentOffset };
    argumentOffset += row.argumentCodecs.length;
    return descriptor;
  });
  const flatCodecs = descriptors.flatMap(({ argumentCodecs }) => argumentCodecs);
  const mask = (codecs) => codecs.map((codec) => `k${codec}`).join(" | ") || "0";
  const header = `// Generated by scripts/generate-script-url-address-classification.mjs. Do not edit.\n#pragma once\n\n#include <cstddef>\n#include <cstdint>\n#include <defold_hermes/script_bridge_capi.hpp>\n\nnamespace defold_hermes::url_binding {\nenum class DispatchStatus : uint8_t { kMissing, kSuccess, kError };\nenum CodecMask : uint16_t {\n  kNil = 1u << 0, kBoolean = 1u << 1, kInteger = 1u << 2, kNumber = 1u << 3,\n  kString = 1u << 4, kHash = 1u << 5, kUrl = 1u << 6, kVector3 = 1u << 7,\n  kVector4 = 1u << 8, kQuaternion = 1u << 9\n};\nenum class ResultCodec : uint8_t { kNone, kNil, kBoolean, kInteger, kNumber, kString, kHash, kHashOrNil, kUrl, kVector3, kVector4, kQuaternion };\nstruct Operation { uint16_t index; uint32_t stableId; const char* canonicalId; const char* module; const char* member; uint16_t argumentOffset; uint8_t requiredArgumentCount; uint8_t maximumArgumentCount; ResultCodec resultCodec; };\nstruct LuaApi { void* context = nullptr; DispatchStatus (*invoke)(void*, const Operation&, const uint16_t*, ScriptCallFrame*, char*, size_t) noexcept = nullptr; };\ninline constexpr size_t kBindingCount = ${descriptors.length};\nconst Operation* operations() noexcept;\nconst Operation* find(uint32_t stableId) noexcept;\nconst uint16_t* argumentCodecs() noexcept;\nDispatchStatus dispatch(ScriptCallFrame*, char*, size_t, const LuaApi*) noexcept;\n}\n`;
  const source = `// Generated by scripts/generate-script-url-address-classification.mjs. Do not edit.\n#include <defold_hermes/generated_script_url_bindings.hpp>\n#include <defold_hermes/script_url_arena.hpp>\n#include <cmath>\n#include <cstdio>\n\nnamespace defold_hermes::url_binding { namespace {\nconstexpr Operation kOperations[] = {\n${descriptors.map((row) => `  {${row.index}, ${row.stableId}u, ${cpp(row.id)}, ${cpp(row.modulePath.join("."))}, ${cpp(row.member)}, ${row.argumentOffset}, ${row.requiredArgumentCount}, ${row.maximumArgumentCount}, ResultCodec::k${row.resultCodec}},`).join("\n")}\n};\nconstexpr uint16_t kArgumentCodecs[] = {\n${flatCodecs.map((codecs) => `  ${mask(codecs)},`).join("\n")}\n};\nbool fail(char* error,size_t capacity,const char* message) noexcept { if(error&&capacity) std::snprintf(error,capacity,"%s",message); return false; }\nuint16_t valueMask(const ScriptValue& value) noexcept {\n  switch(value.tag){\n    case ScriptValueTag::kUndefined: case ScriptValueTag::kNull: return kNil;\n    case ScriptValueTag::kBoolean: return kBoolean;\n    case ScriptValueTag::kNumber: return kInteger|kNumber;\n    case ScriptValueTag::kString: return kString;\n    case ScriptValueTag::kHandle: if(value.handleKind==ScriptHandleKind::kHash)return kHash; if(value.handleKind==ScriptHandleKind::kUrl)return kUrl; return 0;\n    case ScriptValueTag::kDefoldValue: if(value.defoldKind==ScriptDefoldValueKind::kVector3)return kVector3; if(value.defoldKind==ScriptDefoldValueKind::kVector4)return kVector4; if(value.defoldKind==ScriptDefoldValueKind::kQuaternion)return kQuaternion; return 0;\n    default:return 0;\n  }\n}\n}\nconst Operation* operations() noexcept { return kOperations; }\nconst uint16_t* argumentCodecs() noexcept { return kArgumentCodecs; }\nconst Operation* find(uint32_t stableId) noexcept { size_t first=0,count=kBindingCount; while(count){size_t step=count/2,index=first+step;if(kOperations[index].stableId<stableId){first=index+1;count-=step+1;}else count=step;} return first<kBindingCount&&kOperations[first].stableId==stableId?&kOperations[first]:nullptr; }\nDispatchStatus dispatch(ScriptCallFrame* frame,char* error,size_t capacity,const LuaApi* api) noexcept {\n  if(!frame){fail(error,capacity,"URL call frame is null");return DispatchStatus::kError;}\n  const Operation* operation=find(frame->stableId); if(!operation)return DispatchStatus::kMissing; frame->resultCount=0;\n  if(frame->argumentCount<operation->requiredArgumentCount||frame->argumentCount>operation->maximumArgumentCount||(frame->argumentCount&&!frame->arguments)){fail(error,capacity,"URL argument count does not match descriptor");return DispatchStatus::kError;}\n  for(uint32_t index=0;index<frame->argumentCount;++index){const ScriptValue& value=frame->arguments[index];const uint16_t codec=kArgumentCodecs[operation->argumentOffset+index];if(!(valueMask(value)&codec)){fail(error,capacity,"URL argument tag does not match positional codec");return DispatchStatus::kError;}if(value.tag==ScriptValueTag::kNumber&&(codec&kInteger)&&!(codec&kNumber)&&(!std::isfinite(value.number)||std::trunc(value.number)!=value.number)){fail(error,capacity,"URL integer argument is not exact");return DispatchStatus::kError;}if(value.tag==ScriptValueTag::kString&&value.length&&!value.data){fail(error,capacity,"URL string argument has null data");return DispatchStatus::kError;}if(value.tag==ScriptValueTag::kHandle&&value.handleKind==ScriptHandleKind::kUrl){ScriptResolvedUrl ignored{};if(!frame->urlArena||!frame->urlArena->resolve(value,frame->urlArena->runtimeToken(),&ignored)){fail(error,capacity,"URL argument token is stale, collapsed, or belongs to another arena");return DispatchStatus::kError;}}}\n  if(operation->resultCodec!=ResultCodec::kNone&&(!frame->results||frame->resultCapacity<1)){fail(error,capacity,"URL result storage is exhausted");return DispatchStatus::kError;}\n  if(!api||!api->invoke){fail(error,capacity,"URL Lua backend is unavailable");return DispatchStatus::kError;}\n  return api->invoke(api->context,*operation,kArgumentCodecs,frame,error,capacity);\n}\n}\n`;
  const target = `// Generated by scripts/generate-script-url-address-classification.mjs. Do not edit.\nexport const scriptUrlTargetSupport = ${JSON.stringify(report.targetSupport, null, 2)} as const;\nexport const scriptUrlExecutableRouteCount = ${report.routeCount} as const;\n`;
  return { header, source, target };
}

function validateSources(override, sourceTexts) {
  assert(sourceTexts.size === override.sourceEvidence.length, "URL source evidence load is incomplete");
  for (const evidence of override.sourceEvidence) {
    const source = sourceTexts.get(evidence.source);
    assert(typeof source === "string", `${evidence.id}: source was not loaded`);
    assert(sha256(source) === evidence.sha256, `${evidence.id}: reviewed source hash is stale`);
    for (const anchor of evidence.anchors) {
      assert(source.includes(anchor), `${evidence.id}: reviewed source anchor '${anchor}' is stale`);
    }
  }
}

export function generateScriptUrlAddressClassification(inputs) {
  const ir = parse(inputs.irText, "script API IR");
  const patterns = parse(inputs.patternsText, "script binding patterns");
  const override = parse(inputs.overrideText, "URL classification override");
  assert(override.schemaVersion === 1, "URL classification override has an unsupported schema");
  assert(ir.defoldRevision === patterns.defoldRevision &&
    ir.defoldRevision === override.defoldRevision, "URL classification inputs use different Defold revisions");
  validateSources(override, inputs.sourceTexts);

  const irById = uniqueMap(ir.functions, "script API IR");
  uniqueMap(patterns.bindings, "script binding patterns");
  const classified = patterns.bindings.filter((row) => row.loweringFamily === "defold-value");
  assert(classified.length === override.expectedCounts.classifiedDefoldValue,
    `classified defold-value census drifted: expected ${override.expectedCounts.classifiedDefoldValue}, got ${classified.length}`);
  const matrixIds = new Set();
  const urlIds = new Set();
  const urlCandidateIds = new Set();
  const remainderIds = new Set();
  const excludedUrlIds = new Set(override.excludedPreexistingUrlIds);
  assert(excludedUrlIds.size === override.expectedCounts.excludedPreexistingUrl,
    "excluded pre-existing URL route census drifted");
  for (const pattern of classified) {
    const fn = irById.get(pattern.id);
    assert(fn, `${pattern.id}: pattern row is absent from pinned IR`);
    assert(JSON.stringify(pattern.parameterCodecs.map(({ rawType }) => rawType)) ===
      JSON.stringify(fn.parameters.map(({ rawType }) => rawType)) &&
      JSON.stringify(pattern.returnCodecs.map(({ rawType }) => rawType)) === JSON.stringify(fn.returns),
    `${pattern.id}: binding-pattern shapes differ from pinned IR`);
    const types = allTypes(fn);
    if (types.some((type) => type.includes("matrix4"))) matrixIds.add(pattern.id);
    else if (types.some((type) => type.includes("url"))) {
      urlCandidateIds.add(pattern.id);
      if (!excludedUrlIds.has(pattern.id)) urlIds.add(pattern.id);
    }
    else remainderIds.add(pattern.id);
  }
  assert(matrixIds.size === override.expectedCounts.matrix4Disjoint,
    `matrix4 disjoint census drifted: expected ${override.expectedCounts.matrix4Disjoint}, got ${matrixIds.size}`);
  assert(urlIds.size === override.expectedCounts.total,
    `URL/address route count drifted: expected ${override.expectedCounts.total}, got ${urlIds.size}`);
  assert(urlCandidateIds.size === override.expectedCounts.urlCandidates,
    `URL/address candidate count drifted: expected ${override.expectedCounts.urlCandidates}, got ${urlCandidateIds.size}`);
  for (const id of excludedUrlIds) assert(urlCandidateIds.has(id), `${id}: pinned URL exclusion left the candidate set`);
  assert(remainderIds.size === override.expectedCounts.nonMatrixNonUrl,
    `non-matrix/non-URL defold-value census drifted: expected ${override.expectedCounts.nonMatrixNonUrl}, got ${remainderIds.size}`);
  const binaryIds = new Set(override.binaryStringRemainderIds);
  assert(binaryIds.size === override.expectedCounts.binaryStringRemainder,
    "binary-string reviewed remainder count drifted");
  for (const id of binaryIds) assert(remainderIds.has(id), `${id}: reviewed binary-string route left the remainder`);
  const rows = [...urlIds].sort(compare).map((id) => {
    const fn = irById.get(id);
    const urlParameters = fn.parameters.flatMap((parameter, index) => parameter.rawType.includes("url") ? [{
      index,
      name: parameter.rawName,
      rawType: parameter.rawType,
      forms: formsFor(parameter.rawType)
    }] : []);
    assert(urlParameters.length > 0, `${id}: selected URL route has no URL parameter`);
    assert(fn.returns.every((type) => !type.includes("url")),
      `${id}: URL result requires copy-before-pop routing not enabled by this planned classifier`);
    const lastRequiredIndex = fn.parameters.reduce(
      (result, parameter, index) => parameter.optional ? result : index, -1);
    const requiredArgumentCount = lastRequiredIndex + 1;
    const argumentCodecs = fn.parameters.map(({ rawType, optional }) =>
      codecsFor(rawType, optional, id));
    const resultCodec = resultCodecFor(fn.returns, id);
    return {
      id,
      stableId: stableBindingId(id),
      rawName: fn.rawName,
      modulePath: fn.modulePath,
      member: fn.member,
      source: fn.source,
      line: fn.line,
      requiredArgumentCount,
      maximumArgumentCount: fn.parameters.length,
      argumentCodecs,
      resultCodec,
      urlParameters,
      urlResults: [],
      routing: {
        status: "generated-native-dynamic",
        fullUrl: "ScriptUrlArena token -> exact dmMessage::URL -> dmScript::PushURL",
        stringShorthand: "push unchanged Lua string; dmScript::ResolveURL applies captured-instance defaults",
        hashShorthand: "push unchanged Lua hash; dmScript::ResolveURL applies default socket and clears fragment",
        result: "copy dmMessage::URL into ScriptUrlArena before restoring/popping Lua stack"
      },
      targetSupport: override.targetSupport
    };
  });
  assert(new Set(rows.map(({ stableId }) => stableId)).size === rows.length,
    "URL/address route stable-ID collision detected");
  const moduleCounts = countBy(rows, ({ modulePath }) => modulePath.join("."));
  assert(JSON.stringify(moduleCounts) === JSON.stringify(override.expectedCounts.modules),
    `URL/address module census drifted: ${JSON.stringify(moduleCounts)}`);
  const urlParameters = rows.flatMap(({ urlParameters }) => urlParameters);
  assert(urlParameters.length === override.expectedCounts.urlParameters,
    `URL parameter count drifted: expected ${override.expectedCounts.urlParameters}, got ${urlParameters.length}`);
  const rawUrlParameterTypeCounts = countBy(urlParameters, ({ rawType }) => rawType);
  assert(JSON.stringify(rawUrlParameterTypeCounts) === JSON.stringify(override.expectedCounts.rawUrlParameterTypes),
    `URL parameter type census drifted: ${JSON.stringify(rawUrlParameterTypeCounts)}`);

  const inputEvidence = {
    scriptIrSha256: sha256(inputs.irText),
    bindingPatternsSha256: sha256(inputs.patternsText),
    classificationOverrideSha256: sha256(inputs.overrideText),
    defoldSources: [...override.sourceEvidence].sort((a, b) => compare(a.source, b.source)).map(({ id, source, sha256 }) => ({
      id, path: `upstream/defold/${source}`, sha256
    }))
  };
  inputEvidence.aggregateInputSha256 = sha256([
    inputEvidence.scriptIrSha256,
    inputEvidence.bindingPatternsSha256,
    inputEvidence.classificationOverrideSha256,
    ...inputEvidence.defoldSources.map(({ path, sha256 }) => `${path}\0${sha256}`)
  ].join("\0"));

  return {
    schemaVersion: 1,
    defoldRevision: ir.defoldRevision,
    scope: "The exact non-Matrix4 defold-value routes whose pinned IR contains a URL/address parameter",
    coverageClaim: override.coverageClaim,
    allocationClaim: override.allocationClaim,
    routeCount: rows.length,
    urlParameterCount: urlParameters.length,
    moduleCounts,
    rawUrlParameterTypeCounts,
    disjointCensus: {
      classifiedDefoldValue: classified.length,
      matrix4Disjoint: matrixIds.size,
      urlCandidates: urlCandidateIds.size,
      excludedPreexistingUrl: excludedUrlIds.size,
      urlAddressRoutes: rows.length,
      nonMatrixNonUrl: remainderIds.size,
      binaryStringRemainder: binaryIds.size,
      otherNonMatrixNonUrl: remainderIds.size - binaryIds.size
    },
    representationPolicy: {
      fullUrl: "four exact uint64 lanes (socket, reserved, path, fragment) in a generation-checked ScriptUrlArena slot",
      stringShorthand: "distinct string value resolved by Defold against captured Lua caller context",
      hashShorthand: "distinct hash value resolved by Defold as default-socket path with zero fragment",
      collapsedLegacyUrl: "fail-closed: ScriptHandleKind::kUrl with no sidecar slot is never interpreted as a full URL"
    },
    targetSupport: override.targetSupport,
    inputEvidence,
    rows
  };
}

export async function loadScriptUrlAddressInputs() {
  const [irText, patternsText, overrideText] = await Promise.all([
    readFile(urls.ir, "utf8"), readFile(urls.patterns, "utf8"), readFile(urls.override, "utf8")
  ]);
  const override = parse(overrideText, "URL classification override");
  const sourceTexts = new Map(await Promise.all(override.sourceEvidence.map(async ({ source }) => [
    source, await readFile(new URL(`upstream/defold/${source}`, root), "utf8")
  ])));
  return { irText, patternsText, overrideText, sourceTexts };
}

async function main(argv = process.argv.slice(2)) {
  const outputIndex = argv.indexOf("--output");
  const outputPath = outputIndex >= 0 ? argv[outputIndex + 1] : null;
  const consumed = new Set(outputIndex >= 0 ? [outputIndex, outputIndex + 1] : []);
  const unknown = argv.filter((argument, index) => argument !== "--check" && !consumed.has(index));
  if (unknown.length) throw new Error(`Unknown argument: ${unknown[0]}`);
  if (outputIndex >= 0 && (!outputPath || outputPath.startsWith("--"))) {
    throw new Error("--output requires a file path");
  }
  const check = argv.includes("--check");
  if (check && outputPath) throw new Error("--check and --output are mutually exclusive");
  const report = generateScriptUrlAddressClassification(await loadScriptUrlAddressInputs());
  const generated = `${JSON.stringify(report, null, 2)}\n`;
  const runtime = renderRuntime(report);
  if (check) {
    const current = await Promise.all([
      readFile(urls.output, "utf8"), readFile(urls.header, "utf8"),
      readFile(urls.source, "utf8"), readFile(urls.target, "utf8")
    ]);
    const expected = [generated, runtime.header, runtime.source, runtime.target];
    const labels = [urls.output.pathname, urls.header.pathname, urls.source.pathname, urls.target.pathname];
    for (let index = 0; index < current.length; ++index) {
      if (current[index] !== expected[index]) throw new Error(`${labels[index]} is stale; regenerate URL/address bindings`);
    }
  } else {
    if (outputPath) await writeFile(outputPath, generated);
    else await Promise.all([
      writeFile(urls.output, generated), writeFile(urls.header, runtime.header),
      writeFile(urls.source, runtime.source), writeFile(urls.target, runtime.target)
    ]);
  }
  console.log(`${check ? "Verified" : "Generated"} 70 native-dynamic URL/address routes with exact composite sidecars; Static/Wasm and HTML5 full URLs fail closed.`);
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) await main();
